 /// <summary>Tool that simulates searching the web for information on a query.</summary>
 public sealed class WebSearchTool
 {
     [Description("Search the web for information on a given query. Returns relevant search result snippets.")]
     public static string SearchWeb(
         [Description("The search query to look up on the web")] string query)
     {
         // In production, replace with a real search API (e.g., Bing Search, Google Custom Search).
         Console.WriteLine($"  [WebSearch] Searching for: \"{query}\"");

         var results = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
         {
             ["quantum computing"] = """
                 1. Quantum computing uses qubits that can exist in superposition, enabling parallel computation.
                 2. Major players include IBM (127-qubit Eagle), Google (Sycamore), and IonQ (trapped-ion approach).
                 3. Key applications: cryptography, drug discovery, optimization problems, and materials science.
                 4. Current challenges: decoherence, error correction, and scaling qubit counts.
                 5. IBM targets 100,000-qubit systems by 2033. Google claims quantum supremacy was achieved in 2019.
                 """,
             ["artificial intelligence"] = """
                 1. AI encompasses machine learning, deep learning, NLP, computer vision, and robotics.
                 2. Large language models (LLMs) like GPT-4, Claude, and Gemini have transformed NLP since 2022.
                 3. AI is being applied in healthcare, autonomous vehicles, scientific research, and creative arts.
                 4. Concerns include bias, job displacement, safety alignment, and energy consumption.
                 5. Global AI market expected to reach $1.8 trillion by 2030.
                 """,
             ["climate change"] = """
                 1. Global temperatures have risen ~1.1°C above pre-industrial levels as of 2024.
                 2. Main drivers: CO2 from fossil fuels, methane from agriculture, deforestation.
                 3. Effects: rising sea levels, extreme weather, biodiversity loss, food insecurity.
                 4. Paris Agreement targets limiting warming to 1.5°C; current policies track toward 2.7°C.
                 5. Solutions: renewable energy, carbon capture, electrification, and policy reform.
                 """
         };

         foreach (var (key, value) in results)
         {
             if (query.Contains(key, StringComparison.OrdinalIgnoreCase))
                 return value;
         }

         return $"Search results for '{query}': General information found. " +
                "The topic is actively researched with multiple perspectives available. " +
                "Key themes include recent developments, challenges, and future outlook.";
     }
 }

 /// <summary>Tool that allows the agent to take structured research notes.</summary>
 public sealed class NoteTakingTool
 {
     private readonly List<string> _notes = [];

     [Description("Save a research note. Use this to record key findings, facts, or insights discovered during research.")]
     public string SaveNote(
         [Description("The note content to save")] string content,
         [Description("A short category label such as 'finding', 'question', or 'summary'")] string category = "finding")
     {
         var entry = $"[{category.ToUpperInvariant()}] {content}";
         _notes.Add(entry);
         Console.WriteLine($"  [Notes] Saved note #{_notes.Count} ({category})");
         return $"Note saved successfully. You now have {_notes.Count} note(s).";
     }

     [Description("Retrieve all saved research notes to review findings before writing a summary.")]
     public string GetAllNotes()
     {
         if (_notes.Count == 0)
             return "No notes saved yet.";

         Console.WriteLine($"  [Notes] Retrieving {_notes.Count} note(s)");
         return string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
     }
 }

